const version=new URL(self.location.href).searchParams.get('v')||'';importScripts(...['engine.js','eggby-tools.js','unit-tools.js','unit-position-tools.js'].map(f=>'/'+f+(version?'?v='+version:'')));
let topDatabase;
function dealerBenchmarkAccount(){const account=structuredClone(CoopEngine.DEFAULT_PARAMS);account.levelSupreme=account.levelDemonGod=account.levelOther=1;account.lib=0;account.skinLevels=0;account.relicLevel=32;account.eggbyAttached=false;account.heliEggby=false;account.bikerEggby=false;Object.assign(account,{claraLib:'focus',claraMode:'minigun',claraInput:'manual',claraStacks:1e8,claraCount:20,ivyInput:'manual',ivyStacks:1e8,ivyWhispers:99,omenSouls:1e9,omenSoulsFortune:100,omenLord:true,omenLordMode:'finalGiants',omenLordWave:1,gold:1e12,startGold:1e12,bikersUnliberated:20,bikersLiberated:20,cannonBossKills:9999,catStacks:1e8,catAllyHits:1e6,mouseStacks:1e9,mouseStacksFortune:100,spaceStacks:1e8,scalluckPlus:99,slimePlus:99,asuraHeads:999,asuraBodies:999,asuraArms:999,asuraLegs:999,asuraLittles:999,asuraUpgrades:99,heliMoves:999,freezeSetup:{enabled:true,level:CoopData.maxLevelFor('ice-knight'),lib:20,skinLevels:2,relicLevel:32,frostGrade:'SSS',extraSeconds:30}});return account;}
function dealerGrowth(slug){return{level:CoopData.maxLevelFor(slug),lib:CoopData.NO_LIBERATION.has(slug)?0:20,skinLevels:2,relicLevel:32};}
function topDB(){if(!self.indexedDB)return Promise.resolve(null);return topDatabase??=new Promise(resolve=>{const request=indexedDB.open('stack-lab-unit-top-cache',1);request.onupgradeneeded=()=>request.result.createObjectStore('results',{keyPath:'key'});request.onsuccess=()=>resolve(request.result);request.onerror=request.onblocked=()=>resolve(null);});}
async function topKey(input){if(!self.indexedDB||!self.crypto?.subtle)return null;const data=JSON.stringify({version,slug:input.slug,mode:input.mode,target:input.target,growth:input.growth,account:input.account});return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(data))),v=>v.toString(16).padStart(2,'0')).join('');}
async function readTop(key){const db=key&&await topDB();if(!db)return null;return new Promise(resolve=>{try{const request=db.transaction('results').objectStore('results').get(key);request.onsuccess=()=>resolve(request.result?.result||null);request.onerror=()=>resolve(null);}catch{resolve(null);}});}
async function saveTop(key,result){const db=key&&await topDB();if(!db)return;return new Promise(resolve=>{try{const tx=db.transaction('results','readwrite'),store=tx.objectStore('results');store.put({key,result});const count=store.count();count.onsuccess=()=>{let extra=count.result-80;if(extra>0){const cursor=store.openCursor();cursor.onsuccess=()=>{const item=cursor.result;if(item&&extra-->0){item.delete();item.continue();}};}};tx.oncomplete=tx.onerror=tx.onabort=()=>resolve();}catch{resolve();}});}
self.onmessage=async({data})=>{try{const target=CoopTargets.TARGET_BY_ID.get(data.target);if(!target||target.mode!==data.mode)throw Error('계산 대상을 확인하세요.');if(data.kind==='dealer-tier'){const roster=CoopData.demonsIn('supreme'),account=dealerBenchmarkAccount(),rows=[];for(let index=0;index<roster.length;index++){const slug=roster[index].slug,growth=dealerGrowth(slug),modes=slug==='clara'?['minigun','rocket']:[null];let winner=null;for(const claraMode of modes){const currentAccount=structuredClone(account);if(claraMode)currentAccount.claraMode=claraMode;const input=CoopUnitTools.prepareFreeze({...data,slug,growth,account:currentAccount,targetData:target},CoopEngine,CoopData,CoopEggby),optimized=await CoopUnitTools.top(input,CoopEngine,CoopData,CoopEggby,p=>postMessage({id:data.id,kind:'dealer-progress',index,totalUnits:roster.length,slug,evaluated:p.evaluated,total:p.total})),best=optimized.rankings[0],gems=best?.gems||[],checked=CoopUnitTools.row(input,gems,CoopEngine,CoopData,CoopEggby);if(!winner||checked.dps>winner.dps)winner={slug,dps:checked.dps,gems,level:growth.level,lib:growth.lib,freezeShare:input.freezeProfile?.share??0,claraMode:claraMode||null};}rows.push(winner);postMessage({id:data.id,kind:'dealer-progress',index:index+1,totalUnits:roster.length,slug,evaluated:1,total:1});}rows.sort((a,b)=>b.dps-a.dps||a.slug.localeCompare(b.slug));postMessage({id:data.id,kind:'dealer-results',mode:data.mode,target:data.target,rows});return;}if(data.kind==='positions'){if(!Array.isArray(data.sets)||data.sets.length<1||data.sets.length>3)throw Error('비교 조합은 1~3개입니다.');const input={...data,targetData:target},deps={E:CoopEngine,D:CoopData,H:CoopUnitTools,Egg:CoopEggby,G:CoopGeometry,B:CoopBoss,A:CoopAccount},results=[];for(let index=0;index<data.sets.length;index++){const result=await CoopUnitPositions.search({input,picks:data.sets[index],board:data.board,deps,maxEvaluations:80,timeLimit:45000,evaluate:CoopUnitPositions.evaluator(deps,input),onProgress:p=>postMessage({id:data.id,kind:'position-progress',index,...p})});results.push(result);postMessage({id:data.id,kind:'position-row',index,result});}postMessage({id:data.id,kind:'positions',results});return;}const input=CoopUnitTools.prepareFreeze({...data,targetData:target},CoopEngine,CoopData,CoopEggby);if(data.kind==='top'){const key=await topKey(input),cached=!data.force&&await readTop(key);if(cached){postMessage({...cached,id:data.id,kind:'top',cached:true});return;}const result=await CoopUnitTools.top(input,CoopEngine,CoopData,CoopEggby,p=>postMessage({id:data.id,kind:'top-progress',...p}));for(const r of result.rankings){const checked=CoopUnitTools.row(input,r.gems,CoopEngine,CoopData,CoopEggby,true);r.dps=checked.dps;r.formula=checked.formula;}result.rankings.sort(CoopUnitTools.compareDps);const reply={kind:'top',freezeProfile:input.freezeProfile,...result};await saveTop(key,reply);postMessage({id:data.id,...reply});return;}if(data.kind==='recommend'){postMessage({id:data.id,kind:data.kind,freezeProfile:input.freezeProfile,...CoopUnitTools.recommend(input,CoopEngine,CoopData,CoopEggby)});return;}if(!Array.isArray(data.sets)||data.sets.length<1||data.sets.length>3)throw Error('비교 조합은 1~3개입니다.');postMessage({id:data.id,freezeProfile:input.freezeProfile,rows:data.sets.map(g=>CoopUnitTools.row(input,g,CoopEngine,CoopData,CoopEggby,true))});}catch(e){postMessage({id:data.id,error:e.message});}};
